public class Solution {
    // CONTRACT: count of words STRICTLY longer than the average length.
    // Precondition: words.length >= 1.
    public static int longWords(String[] words) {
        int sum = 0;
        for (String w : words) {
            sum += w.length();
        }
        double avg = sum / words.length;   // BUG: integer division
        int count = 0;
        for (String w : words) {
            if (w.length() > avg) {
                count++;
            }
        }
        return count;
    }
}

